-- goal-plays-new-goals.sql
--
-- Adds the four goals the catalog does not tag yet: bigger checks, catering and private events,
-- own your takeout, and get known around here. Between them they give a door to eleven services
-- that are already built, priced and deliverable but that no goal could previously ask for.
--
-- Apply in the Supabase Dashboard SQL editor (not the CLI — db push would re-run every migration),
-- then republish the catalog:  npx tsx scripts/gen-catalog.ts
-- Then delete the `pending` arrays in src/lib/campaigns/data/plan-goals.ts; the derivation will
-- already be returning these exact ids and priorities.
--
-- Idempotent: each statement skips a service that already carries the goal.
-- Generated by scripts/tmp/gen-goal-sql.ts from PLAN_GOALS — do not hand-edit.

-- Bigger checks (bigger-checks)
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Engineer the menu so guests trade up: pairings, add-ons, high-margin features.","stage":"reason","weight":9,"minTier":"standard"}]'::jsonb
  where id = 'menu-eng' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Design the offer math so a bump in spend does not come out of your margin.","stage":"easy","weight":8,"minTier":"standard"}]'::jsonb
  where id = 'incentive-design' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Shoot the high-margin items properly, because people order what looks best.","stage":"reason","weight":3,"minTier":"lean"}]'::jsonb
  where id = 'photo-library' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Put the items you want ordered where they get seen and read.","stage":"easy","weight":3,"minTier":"lean"}]'::jsonb
  where id = 'site-menu' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Measure spend per guest, so you can tell whether any of this moved it.","stage":"backstage","weight":3,"minTier":"lean"}]'::jsonb
  where id = 'tracking' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"bigger-checks","role":"Monthly read on average check and which items are actually carrying it.","stage":"backstage","weight":4,"minTier":"standard"}]'::jsonb
  where id = 'reporting' and not (goal_plays @> '[{"goal":"bigger-checks"}]'::jsonb);

