  where id = 'brand-kit' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"get-known","role":"Pitch your story to local writers, lists and guides.","stage":"found","weight":8,"minTier":"standard"}]'::jsonb
  where id = 'pr-media' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"get-known","role":"A dedicated shoot for the piece you actually want people to see.","stage":"found","weight":7,"minTier":"standard"}]'::jsonb
  where id = 'video-single' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"get-known","role":"Keep your pages active, which is where most people check you out first.","stage":"found","weight":9,"minTier":"standard"}]'::jsonb
  where id = 'social-mgmt' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"get-known","role":"The image library everything else draws from.","stage":"reason","weight":3,"minTier":"lean"}]'::jsonb
  where id = 'photo-library' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);
update catalog_services set goal_plays = coalesce(goal_plays, '[]'::jsonb) || '[{"goal":"get-known","role":"Measure whether any of it turned into people looking you up.","stage":"backstage","weight":3,"minTier":"lean"}]'::jsonb
  where id = 'tracking' and not (goal_plays @> '[{"goal":"get-known"}]'::jsonb);

-- verify: every new goal should report the expected service count
select p->>'goal' as goal, count(*) as services
from catalog_services, jsonb_array_elements(goal_plays) p
where p->>'goal' in ('bigger-checks','catering','own-takeout','get-known')
group by 1 order by 1;
